function solve({config,state,event}) {
  let s=state||{a:[],e:{}};
  const key=event.key, type=event.type;
  let x=s.e[key], status='ignored', value=null;
  const live=z=>z&&!z.t;
  if(type==='put'){
    if(x){
      if(x.t) status='blocked'; else {x.v=event.value;status='stored';}
    }else{
      if(s.a.length>=config.capacity){
        let j=-1;
        for(let i=0;i<s.a.length;i++){let q=s.e[s.a[i]];if(q.p===0){j=i;break;}}
        if(j<0) status='blocked';
        else {let k=s.a.splice(j,1)[0];delete s.e[k];}
      }
      if(!s.e[key]&&s.a.length<config.capacity){s.a.push(key);s.e[key]={v:event.value,p:0,t:false};status='stored';}
    }
  }else if(type==='pin'){
    if(live(x)){x.p++;status='pinned';}else status='missing';
  }else if(type==='unpin'){
    if(x&&x.p>0){x.p--;status='released';if(x.t&&x.p===0){let i=s.a.indexOf(key);if(i>=0)s.a.splice(i,1);delete s.e[key];status='removed';}}else status='ignored';
  }else if(type==='invalidate'){
    if(!x)status='missing';else if(x.p>0){x.t=true;status='invalidated';}else{let i=s.a.indexOf(key);if(i>=0)s.a.splice(i,1);delete s.e[key];status='removed';}
  }else if(type==='get'){
    if(live(x)){status='hit';value=x.v;}else status='miss';
  }
  let pins={}, tomb=[];for(const k of s.a){let q=s.e[k];pins[k]=q.p;if(q.t)tomb.push(k)}tomb.sort();
  return {state:s,output:{status,value,order:s.a.slice(),pins,tombstones:tomb}};
}
